trait Descriptor {                       // the trait IS the descriptor
    type Value;                            // associated type = the traits payload
    const NAME: &'static str;              // per-type constant
    fn key(&self) -> u64;
}
impl Descriptor for Frame {
    type Value = Bytes;
    const NAME: &'static str = "frame";
    fn key(&self) -> u64 { self.crc }
}
fn render<T: Descriptor>(v: &T) -> String { format!("{}:{}", T::NAME, v.key()) }
